    0.5 + (0.08 + 0.18 * var(--aurora-speak)) * var(--orb-level) +
      (0.06 + 0.26 * var(--aurora-speak)) * var(--orb-treble)
  );
  -webkit-mask-image: linear-gradient(to bottom, black 18%, transparent 76%);
  mask-image: linear-gradient(to bottom, black 18%, transparent 76%);
  animation: aurora-sway-b calc(13.3s / var(--orb-speed)) ease-in-out -4.1s infinite;
}

.veilFront {
  filter: blur(8px);
  opacity: calc(
    (
        0.08 + (0.2 + 0.4 * var(--aurora-speak)) * var(--orb-level) +
          (0.16 + 0.44 * var(--aurora-speak)) * var(--orb-treble)
      ) *
      (1 - var(--aurora-pulse-mix) - var(--aurora-think-mix)) +
      (0.06 + 0.44 * var(--aurora-pulse-slow)) * var(--aurora-pulse-mix) +
      (0.14 + 0.5 * var(--aurora-pulse)) * var(--aurora-think-mix)
  );
  -webkit-mask-image: linear-gradient(to bottom, black 10%, black 34%, transparent 66%);
  mask-image: linear-gradient(to bottom, black 10%, black 34%, transparent 66%);
  animation:
    aurora-sway-c calc(9.7s / var(--orb-speed)) ease-in-out -2.9s infinite,
    aurora-pulse calc(4.6s / var(--orb-speed)) ease-in-out infinite;
}

.drift {
