export const EqualizerOrbTw = ({
  state = 'idle',
  size = 168,
  speed = 1,
  colorFrom = '#38bdf8',
  colorTo = '#818cf8',
  levelRef,
  label = 'Assistant orb',
  className,
  ref,
}: OrbProps) => {
  const innerRef = useRef<HTMLDivElement>(null);
  useOrbLevel(innerRef, state, levelRef, undefined, speed);
  const setRef = useCallback(
    (node: HTMLDivElement | null) => {
      innerRef.current = node;
      if (typeof ref === 'function') ref(node);
      else if (ref) ref.current = node;
    },
    [ref],
  );

  return (
    <div
      ref={setRef}
      role="img"
      aria-label={label}
      data-state={state}
      data-equalizer-orb-tw=""
      className={clsx('relative isolate grid place-items-center', className)}
      style={{
        ...orbVars({ size, speed, colorFrom, colorTo }),
        width: size,
        height: size,
      }}
    >
      <style>{EQ_TW_CSS}</style>
      <span data-eq-ring="" className="absolute inset-0 z-0 rounded-full" />
      <span
        data-eq-disc=""
        className="absolute inset-[3.5%] z-[1] grid place-items-center overflow-hidden rounded-full"
      >
        <span
          data-eq-halo=""
          className="absolute z-0 h-[86%] w-[86%] rounded-full blur-[24px] will-change-[transform,opacity]"
        />
        <span
          data-eq-core=""
          className="absolute z-[1] h-[44%] w-[44%] rounded-full blur-[6px] will-change-[transform,opacity]"
        />
        <span data-eq-bars="" className="relative z-[2] grid h-[58%] w-[68%]">
          {LAYERS.map((layer) => (
            <span
              key={layer}
              data-layer={layer}
              className="col-start-1 row-start-1 flex h-full w-full items-center justify-center gap-[6%]"
            >
              {BARS.map((bar, index) => (
                <span
                  key={bar.delay}
                  data-bar={index + 1}
                  className="w-[8%] rounded-full"
                  style={
                    {
                      height: bar.h,
                      '--bar-level': bar.level,
                      '--bar-gain': `${bar.gain}`,
                      '--bar-hue': `${bar.hue}`,
                      '--bar-i': `${index}`,
                      '--bar-dur': bar.dur,
                      '--bar-delay': bar.delay,
                      '--bar-ease': bar.ease,
                    } as CSSProperties
                  }
                />
              ))}
            </span>
          ))}
        </span>
      </span>
    </div>
  );
};

@property --eq-from {
  syntax: '<color>';
  inherits: true;
  initial-value: #38bdf8;
}

@property --eq-to {
  syntax: '<color>';
  inherits: true;
  initial-value: #818cf8;
}

@property --eq-ring {
  syntax: '<number>';
  inherits: true;
  initial-value: 0;
}

@property --eq-breathe {
  syntax: '<number>';
  inherits: true;
  initial-value: 0;
}

@property --eq-talk {
  syntax: '<number>';
  inherits: true;
  initial-value: 0;
}

@property --eq-shake {
  syntax: '<number>';
  inherits: true;
  initial-value: 0;
}

.orb {
  --orb-size: 168px;
  --orb-speed: 1;
  --orb-color-from: #38bdf8;
  --orb-color-to: #818cf8;
  --orb-level: 0;
  --orb-bass: 0;
  --orb-mid: 0;
  --orb-treble: 0;
  --eq-from: var(--orb-color-from);
  --eq-to: var(--orb-color-to);
  --eq-ring: 0;
  --eq-breathe: 0;
  --eq-shake: 0;
  --eq-talk: 0;
  --orb-dur: 0.2s;
  --orb-ease: cubic-bezier(0.16, 1, 0.3, 1);
  --eq-ink: color-mix(in oklab, var(--eq-from) 45%, #0f172a);
  --eq-halo-mix: color-mix(in oklab, var(--eq-from), var(--eq-to) 60%);
  --eq-surface-hi: color-mix(in oklab, var(--eq-from) 10%, #ffffff);
  --eq-surface-lo: color-mix(in oklab, var(--eq-to) 16%, #e9edf7);
  --eq-rim: color-mix(in oklab, var(--eq-from) 38%, #b9c3d8);
  --eq-sheen: rgb(255 255 255 / 0.65);
  --eq-vignette: color-mix(in oklab, #0f172a, transparent 84%);
  --eq-glow-halo: color-mix(in oklab, var(--eq-halo-mix), transparent 35%);
  --eq-glow-core: color-mix(in oklab, var(--eq-from), transparent 25%);
  --eq-shadow-tint: color-mix(in oklab, var(--eq-ink), transparent 40%);
  --eq-shadow-tint-active: color-mix(in oklab, var(--eq-ink), transparent 28%);
  --eq-shadow-glow: transparent;
  --eq-shadow-glow-active: transparent;
  --eq-shadow:
    0 14px 28px -16px var(--eq-shadow-tint),
    0 0 26px -8px var(--eq-shadow-glow);
  --eq-shadow-active:
    0 16px 34px -16px var(--eq-shadow-tint-active),
    0 0 40px -6px var(--eq-shadow-glow-active);
