  display: grid;
  place-items: center;
  width: var(--orb-size);
  height: var(--orb-size);
  isolation: isolate;
  transition-property:
    opacity, filter, --eq-from, --eq-to, --eq-ring, --eq-breathe, --eq-shake, --eq-talk;
  transition-duration: var(--orb-dur);
  transition-timing-function: var(--orb-ease);
}

