    );
    --eq-glow-core: light-dark(
      color-mix(in oklab, var(--eq-from), transparent 25%),
      var(--eq-from)
    );
    --eq-shadow-tint: light-dark(
      color-mix(in oklab, var(--eq-ink), transparent 40%),
      rgb(0 0 0 / 0.6)
    );
    --eq-shadow-tint-active: light-dark(
      color-mix(in oklab, var(--eq-ink), transparent 28%),
      rgb(0 0 0 / 0.55)
    );
    --eq-shadow-glow: light-dark(
      transparent,
      color-mix(in oklab, var(--eq-from), transparent 68%)
    );
    --eq-shadow-glow-active: light-dark(
      transparent,
