    const cx = size / 2;
    const cy = size / 2;
    const R = size * 0.435;
    const supportsConic = typeof ctx.createConicGradient === 'function';

    const makeSprite = () => {
      const c = document.createElement('canvas');
      c.width = Math.max(1, Math.round(size * dpr));
