  --orb-speed: 1;
  --orb-color-from: #a78bfa;
  --orb-color-to: #38bdf8;
  --orb-level: 0;
  --glass-from: var(--orb-color-from);
  --glass-to: var(--orb-color-to);
  --glass-breathe: 0;
  --glass-halo-base: 0.72;
  --glass-halo-gain: 0.28;
  --glass-halo-swell: 0.14;
  --glass-rim-base: 0.85;
  --glass-rim-gain: 0;
  --glass-blend: color-mix(in oklab, var(--glass-from), var(--glass-to) 50%);
  --glass-fill: light-dark(
    color-mix(in oklab, var(--glass-blend), transparent 62%),
    color-mix(in oklab, var(--glass-blend), transparent 86%)
  );
  --glass-edge: light-dark(
    color-mix(in oklab, color-mix(in oklab, var(--glass-from), #171a2b 55%), transparent 35%),
    color-mix(in oklab, #ffffff, transparent 66%)
  );
  --glass-depth: light-dark(
    color-mix(in oklab, color-mix(in oklab, var(--glass-from), #10131f 42%), transparent 46%),
    color-mix(in oklab, color-mix(in oklab, var(--glass-from), #05060c 52%), transparent 36%)
  );
  --glass-contact: light-dark(
    color-mix(in oklab, color-mix(in oklab, var(--glass-from), #10131f 55%), transparent 50%),
    color-mix(in oklab, color-mix(in oklab, var(--glass-blend), #000000 40%), transparent 42%)
  );
  --glass-halo-tight: light-dark(color-mix(in oklab, var(--glass-blend), transparent 32%), transparent);
  --glass-halo-wide: light-dark(transparent, color-mix(in oklab, var(--glass-blend), transparent 42%));
  --glass-caustic: color-mix(in oklab, color-mix(in oklab, var(--glass-to), #ffffff 55%), transparent 28%);
  --glass-spec-counter: color-mix(in oklab, color-mix(in oklab, var(--glass-to), #ffffff 42%), transparent 70%);
  position: relative;
  display: grid;
  place-items: center;
  width: var(--orb-size);
  height: var(--orb-size);
  isolation: isolate;
  --orb-dur: 0.2s;
  --orb-ease: cubic-bezier(0.16, 1, 0.3, 1);
  transition-property:
    --glass-from, --glass-to, --glass-breathe, --glass-halo-base, --glass-halo-gain,
