.orb:is([data-state='idle'], [data-state='disabled']) {
  --orb-dur: 0.6s;
  --orb-ease: cubic-bezier(0.65, 0, 0.35, 1);
}

.halo {
  position: absolute;
  inset: -8%;
  border-radius: 50%;
  background:
    radial-gradient(closest-side, var(--glass-halo-tight) 18%, transparent 66%),
    radial-gradient(closest-side, var(--glass-halo-wide) 10%, transparent 96%);
  opacity: calc(var(--glass-halo-base) + var(--glass-halo-gain) * var(--orb-level));
  transform: scale(calc(1 + var(--glass-halo-swell) * var(--orb-level)));
}

.aura {
  position: absolute;
  inset: 2.5%;
  border-radius: 50%;
  background: conic-gradient(
    from 20deg,
    var(--glass-from),
    color-mix(in oklch, var(--glass-from), #ff3ea5 34%) 18%,
    var(--glass-to) 42%,
    color-mix(in oklch, var(--glass-to), #ffb54d 30%) 64%,
    color-mix(in oklch, var(--glass-from), #ffffff 24%) 82%,
    var(--glass-from)
  );
  filter: blur(14px);
  opacity: calc(0.62 + 0.38 * var(--orb-level));
  animation:
    glass-rotate calc(9s / var(--orb-speed)) linear infinite,
    glass-hue calc(16s / var(--orb-speed)) ease-in-out infinite alternate;
}

.sphere {
  position: absolute;
  inset: 10%;
  border-radius: 50%;
  background-color: var(--glass-fill);
  background-image:
    radial-gradient(60% 30% at 50% 96%, var(--glass-caustic), transparent 70%),
    radial-gradient(85% 60% at 50% 112%, var(--glass-depth), transparent 74%),
