  backdrop-filter: blur(10px) saturate(1.5) brightness(1.05);
  box-shadow:
    inset 0 0 0 1px var(--glass-edge),
    inset 0 2px 10px color-mix(in oklab, #ffffff, transparent 62%),
    inset 0 -12px 26px var(--glass-depth),
    0 16px 36px -14px var(--glass-contact);
