  animation: glass-breathe calc(3.2s / var(--orb-speed)) ease-in-out infinite;
}

.sheen {
  position: absolute;
  inset: 10%;
  border-radius: 50%;
  background: conic-gradient(
    from 40deg,
    transparent 0deg 60deg,
    rgba(255, 255, 255, 0.85) 102deg,
    transparent 148deg 236deg,
    color-mix(in oklab, #ffffff, transparent 55%) 268deg,
    transparent 306deg
  );
  opacity: 0.12;
  -webkit-mask: radial-gradient(closest-side, #000 52%, rgba(0, 0, 0, 0.35) 78%, transparent 97%);
  mask: radial-gradient(closest-side, #000 52%, rgba(0, 0, 0, 0.35) 78%, transparent 97%);
  animation: glass-rotate calc(14s / var(--orb-speed)) linear infinite;
}

.rim {
  position: absolute;
  inset: 10%;
  border-radius: 50%;
