  disabled: 0.2,
};

const CORE_SCALE: Record<OrbState, number> = {
  idle: 0.94,
  connecting: 0.97,
  listening: 1.04,
  thinking: 0.99,
  speaking: 1.07,
  error: 1,
  disabled: 0.9,
};

const glowLayer = (
  from: string,
  to: string,
  opacity: number,
  fade: string | undefined,
): CSSProperties => ({
  position: 'absolute',
  inset: '-16%',
  borderRadius: '50%',
  background: `radial-gradient(circle at 50% 44%, color-mix(in srgb, ${to} 32%, transparent) 0%, color-mix(in srgb, ${from} 20%, transparent) 44%, transparent 70%)`,
  opacity,
  transition: fade,
});

export const NebulaOrb = ({
  state = 'idle',
  size = 180,
  speed = 1,
  colorFrom = '#8b5cf6',
  colorTo = '#22d3ee',
  levelRef,
  label = 'Assistant orb',
  className,
  ref,
}: OrbProps) => {
  const reduced = useReducedMotion();
  const webgl = useWebGLSupport();
  const [ready, setReady] = useState(false);
  const handleReady = useCallback(() => setReady(true), []);
  const sceneShown = webgl === true && ready;
  const fade = reduced ? undefined : 'opacity 600ms ease';
  const glow = GLOW[state];
  const isError = state === 'error';
  const vars = {
    '--nebula-from': colorFrom,
    '--nebula-to': colorTo,
    '--nebula-error-from': ERROR_COLOR_FROM,
    '--nebula-error-to': ERROR_COLOR_TO,
    '--nebula-live-from': isError ? ERROR_COLOR_FROM : colorFrom,
    '--nebula-live-to': isError ? ERROR_COLOR_TO : colorTo,
  } as CSSProperties;
  return (
    <div
      ref={ref}
      role="img"
      aria-label={label}
      className={className}
      style={{
        ...vars,
        position: 'relative',
        width: size,
        height: size,
        opacity: state === 'disabled' ? 0.5 : 1,
        filter: state === 'disabled' ? 'grayscale(0.85)' : undefined,
        transition: reduced ? undefined : 'opacity 400ms ease, filter 400ms ease',
      }}
    >
      <div
        aria-hidden
        style={glowLayer('var(--nebula-from)', 'var(--nebula-to)', isError ? 0 : glow, fade)}
      />
      <div
        aria-hidden
        style={glowLayer(
          'var(--nebula-error-from)',
          'var(--nebula-error-to)',
          isError ? glow : 0,
          fade,
        )}
      />
      <div
        aria-hidden
        style={{
          position: 'absolute',
          left: '17%',
          right: '17%',
          bottom: '-6%',
          height: '13%',
          borderRadius: '50%',
          background:
            'radial-gradient(ellipse at center, rgba(15, 23, 42, 0.3) 0%, rgba(15, 23, 42, 0.12) 45%, transparent 72%)',
          opacity: 0.4 + glow * 0.5,
          transition: fade,
        }}
      />
      <div
        aria-hidden
        style={{
          position: 'absolute',
          inset: '10%',
          borderRadius: '50%',
          background:
            'radial-gradient(circle at 36% 30%, color-mix(in srgb, var(--nebula-live-to) 62%, white) 0%, color-mix(in srgb, var(--nebula-live-to) 55%, var(--nebula-live-from)) 24%, var(--nebula-live-from) 60%, color-mix(in srgb, var(--nebula-live-from) 50%, black) 100%)',
          opacity: sceneShown ? 0 : 0.55 + glow * 0.45,
          transform: `scale(${CORE_SCALE[state]})`,
          transition: reduced ? undefined : 'opacity 600ms ease, transform 600ms ease',
        }}
      />
      {webgl === true && (
        <div
          style={{
            position: 'absolute',
            inset: 0,
            opacity: ready ? 1 : 0,
            transition: reduced ? undefined : 'opacity 500ms ease',
          }}
        >
          <NebulaScene
            state={state}
            speed={speed}
            colorFrom={colorFrom}
            colorTo={colorTo}
            levelRef={levelRef}
            onReady={handleReady}
          />
        </div>
      )}
    </div>
  );
};

files.src/registry/orbe/nebula-orb/nebula-scen:
'use client';

import { useEffect, useMemo, useRef, useState } from 'react';
import type { RefObject } from 'react';
import { Canvas, useFrame, useThree } from '@react-three/fiber';
import * as THREE from 'three';
import {
  approach,
  createStateMix,
  stateEnergy,
  ERROR_COLOR_FROM,
  ERROR_COLOR_TO,
  type OrbState,
  type StateMix,
} from '../../lib/orb-state';
import { observeActivity } from '../../lib/use-in-view';
import { useReducedMotion } from '../../lib/use-reduced-motion';

const noiseGLSL = /* glsl */ `
vec4 permute(vec4 x){ return mod(((x*34.0)+1.0)*x, 289.0); }
vec4 taylorInvSqrt(vec4 r){ return 1.79284291400159 - 0.85373472095314 * r; }

float snoise(vec3 v){
  const vec2 C = vec2(1.0/6.0, 1.0/3.0);
  const vec4 D = vec4(0.0, 0.5, 1.0, 2.0);
  vec3 i = floor(v + dot(v, C.yyy));
  vec3 x0 = v - i + dot(i, C.xxx);
  vec3 g = step(x0.yzx, x0.xyz);
  vec3 l = 1.0 - g;
  vec3 i1 = min(g.xyz, l.zxy);
  vec3 i2 = max(g.xyz, l.zxy);
  vec3 x1 = x0 - i1 + 1.0 * C.xxx;
  vec3 x2 = x0 - i2 + 2.0 * C.xxx;
  vec3 x3 = x0 - 1.0 + 3.0 * C.xxx;
  i = mod(i, 289.0);
  vec4 p = permute(permute(permute(
            i.z + vec4(0.0, i1.z, i2.z, 1.0))
          + i.y + vec4(0.0, i1.y, i2.y, 1.0))
          + i.x + vec4(0.0, i1.x, i2.x, 1.0));
  float n_ = 1.0/7.0;
  vec3 ns = n_ * D.wyz - D.xzx;
  vec4 j = p - 49.0 * floor(p * ns.z *ns.z);
  vec4 x_ = floor(j * ns.z);
  vec4 y_ = floor(j - 7.0 * x_);
  vec4 x = x_ *ns.x + ns.yyyy;
  vec4 y = y_ *ns.x + ns.yyyy;
  vec4 h = 1.0 - abs(x) - abs(y);
  vec4 b0 = vec4(x.xy, y.xy);
  vec4 b1 = vec4(x.zw, y.zw);
  vec4 s0 = floor(b0)*2.0 + 1.0;
  vec4 s1 = floor(b1)*2.0 + 1.0;
  vec4 sh = -step(h, vec4(0.0));
  vec4 a0 = b0.xzyw + s0.xzyw*sh.xxyy;
  vec4 a1 = b1.xzyw + s1.xzyw*sh.zzww;
  vec3 p0 = vec3(a0.xy, h.x);
  vec3 p1 = vec3(a0.zw, h.y);
  vec3 p2 = vec3(a1.xy, h.z);
  vec3 p3 = vec3(a1.zw, h.w);
  vec4 norm = taylorInvSqrt(vec4(dot(p0,p0), dot(p1,p1), dot(p2,p2), dot(p3,p3)));
  p0 *= norm.x; p1 *= norm.y; p2 *= norm.z; p3 *= norm.w;
  vec4 m = max(0.6 - vec4(dot(x0,x0), dot(x1,x1), dot(x2,x2), dot(x3,x3)), 0.0);
  m = m * m;
  return 42.0 * dot(m*m, vec4(dot(p0,x0), dot(p1,x1), dot(p2,x2), dot(p3,x3)));
}
`;

const vertexShader = /* glsl */ `
uniform float uTime;
uniform float uAudio;
uniform float uDistort;
uniform float uFreq;
uniform float uFreqBoost;
uniform float uSpin;
uniform float uBreath;
varying float vNoise;
varying vec3 vPos;
varying vec3 vNormal;
varying vec3 vViewDir;

${noiseGLSL}

float fbm(vec3 p){
  float n = snoise(p * 1.1);
  n += snoise(p * 2.4) * 0.4;
  n += snoise(p * 5.0) * 0.15;
  return n * 0.35;
}

vec3 rotateY(vec3 p, float a){
  float c = cos(a);
  float s = sin(a);
  return vec3(c * p.x + s * p.z, p.y, c * p.z - s * p.x);
}

vec3 warpDomain(vec3 p, float freq){
  return rotateY(p, uSpin) * freq + uTime * vec3(0.12, 0.27, 0.08);
}

float fieldNoise(vec3 p){
  if (uFreqBoost >= 0.999) return fbm(warpDomain(p, 1.45));
  float n = fbm(warpDomain(p, uFreq));
  if (uFreqBoost > 0.001) n = mix(n, fbm(warpDomain(p, 1.45)), uFreqBoost);
  return n;
}

vec3 surfacePoint(vec3 p, float amp){
  return p + normalize(p) * fieldNoise(p) * amp;
}

void main(){
  float amp = uDistort * 0.55 + uAudio * 0.3;
  float radius = length(position);
  vec3 dir = normalize(position);
  float noise = fieldNoise(position);
  vec3 displaced = position + dir * noise * amp;

  vec3 axis = abs(dir.y) < 0.99 ? vec3(0.0, 1.0, 0.0) : vec3(1.0, 0.0, 0.0);
  vec3 tangent = normalize(cross(dir, axis));
  vec3 bitangent = cross(dir, tangent);
  float eps = 0.01;
  vec3 pT = surfacePoint(normalize(position + tangent * eps) * radius, amp);
  vec3 pB = surfacePoint(normalize(position + bitangent * eps) * radius, amp);
  vec3 bent = normalize(cross(pT - displaced, pB - displaced));

  vNoise = noise;
  vPos = rotateY(position, uSpin);
  vec4 mv = modelViewMatrix * vec4(displaced * uBreath, 1.0);
  vNormal = normalize(normalMatrix * bent);
  vViewDir = normalize(-mv.xyz);
  gl_Position = projectionMatrix * mv;
}
`;

const fragmentShader = /* glsl */ `
uniform vec3 uColorFrom;
uniform vec3 uColorTo;
uniform float uTime;
uniform float uAudio;
uniform float uRim;
uniform float uShimmerPhase;
varying float vNoise;
varying vec3 vPos;
varying vec3 vNormal;
varying vec3 vViewDir;

${noiseGLSL}

float hash(vec2 p){
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

void main(){
  vec3 N = normalize(vNormal);
  vec3 V = normalize(vViewDir);

  float warp = snoise(vPos * 1.6 + uTime * vec3(0.1, 0.22, 0.0));
  float blend = clamp(0.5 + vNoise * 1.4 + warp * 0.3 + vPos.y * 0.1, 0.0, 1.0);
  vec3 base = mix(uColorFrom * 0.45, uColorFrom, smoothstep(0.0, 0.55, blend));
  base = mix(base, uColorTo, smoothstep(0.5, 1.0, blend));

  vec3 key = normalize(vec3(0.6, 0.8, 0.5));
  float lambert = dot(N, key) * 0.5 + 0.5;
  float diffuse = lambert * lambert;
  vec3 fillDir = normalize(vec3(-0.55, -0.35, 0.4));
  float fill = max(dot(N, fillDir), 0.0);
  vec3 halfway = normalize(key + V);
  float specular = pow(max(dot(N, halfway), 0.0), 48.0) * 0.35;

  float fres = pow(1.0 - max(dot(N, V), 0.0), 2.6);
  float pulse = 0.5 + 0.5 * sin(uTime * 3.0);
  vec3 rimColor = mix(uColorTo, vec3(1.0), 0.3);

  vec3 col = base * (0.32 + diffuse * 1.15);
  col += vec3(0.42, 0.48, 0.7) * fill * 0.22;
  col += vec3(specular);
  col += rimColor * fres * (0.42 + uAudio * 0.38 + uRim * pulse * 0.55);
  col = col / (1.0 + col * 0.6);

  float grain = hash(gl_FragCoord.xy + uShimmerPhase * 43.7);
  col *= 1.0 + (grain - 0.5) * 0.08;

  gl_FragColor = vec4(col, 1.0);
}
`;

const STATE_KEYS = [
  'idle',
  'connecting',
  'listening',
  'thinking',
  'speaking',
  'error',
  'disabled',
] as const satisfies readonly OrbState[];

const DISTORT: Record<OrbState, number> = {
  idle: 0.3,
  connecting: 0.3,
  listening: 0.34,
  thinking: 0.46,
  speaking: 0.38,
  error: 0.34,
  disabled: 0.24,
};

const FREQ: Record<OrbState, number> = {
  idle: 1,
  connecting: 1,
  listening: 1,
  thinking: 0.85,
  speaking: 1.1,
  error: 1.25,
  disabled: 0.9,
};

const RESPONSE: Record<OrbState, number> = {
  idle: 8,
  connecting: 8,
  listening: 14,
  thinking: 8,
  speaking: 10,
  error: 8,
  disabled: 8,
};

const ENERGY_RANGE: Partial<Record<OrbState, readonly [number, number]>> = {
  connecting: [0.12, 0.1],
  listening: [0.4, 0.5],
  thinking: [0.24, 0.2],
  speaking: [0.3, 0.4],
};

const smoothEnergy = (state: OrbState, t: number): number => {
  const energy = stateEnergy(state, t);
  const range = ENERGY_RANGE[state];
  if (!range) return energy;
  const u = Math.min(Math.max((energy - range[0]) / range[1], 0), 1);
  return range[0] + range[1] * u * u;
};

interface SphereProps {
  state: OrbState;
  speed: number;
  colorFrom: string;
  colorTo: string;
  reduced: boolean;
  levelRef?: RefObject<number>;
  onReady?: () => void;
}

const Sphere = ({ state, speed, colorFrom, colorTo, reduced, levelRef, onReady }: SphereProps) => {
  const matRef = useRef<THREE.ShaderMaterial>(null);
  const invalidate = useThree((three) => three.invalidate);
  const clock = useRef(0);
  const smoothed = useRef(0);
  const spin = useRef(0);
  const shimmer = useRef(0);
  const mixRef = useRef<StateMix | null>(null);
  const readyRef = useRef(false);
  const palette = useRef({
    from: new THREE.Color(colorFrom),
    to: new THREE.Color(colorTo),
    errorFrom: new THREE.Color(ERROR_COLOR_FROM),
    errorTo: new THREE.Color(ERROR_COLOR_TO),
  });

  const uniforms = useMemo(
    () => ({
      uTime: { value: 0 },
      uAudio: { value: 0 },
      uDistort: { value: 0.3 },
      uFreq: { value: 1 },
      uFreqBoost: { value: 0 },
      uSpin: { value: 0 },
      uBreath: { value: 1 },
      uRim: { value: 0 },
      uShimmerPhase: { value: 0 },
      uColorFrom: { value: new THREE.Color() },
      uColorTo: { value: new THREE.Color() },
    }),
    [],
  );

  useEffect(() => {
    palette.current.from.set(colorFrom);
    palette.current.to.set(colorTo);
    invalidate();
  }, [colorFrom, colorTo, invalidate]);

  useEffect(() => {
    invalidate();
  }, [state, invalidate]);

  useFrame((_, delta) => {
    const u = matRef.current?.uniforms;
    if (!u) return;
    if (!mixRef.current) mixRef.current = createStateMix(state);
    const dt = Math.min(delta, 0.1);
    if (!reduced) clock.current += dt * Math.max(0, speed);
    const t = clock.current;

    const weights = reduced
      ? mixRef.current.update(state, 1, 1000)
      : mixRef.current.update(state, dt);

    let distort = 0;
    let freq = 0;
    let response = 0;
    let energy = 0;
    for (const key of STATE_KEYS) {
      const w = weights[key];
      if (w === 0) continue;
      distort += w * DISTORT[key];
      freq += w * FREQ[key];
      response += w * RESPONSE[key];
      energy += w * smoothEnergy(key, t);
    }

    const live = levelRef?.current;
    const hasLive = typeof live === 'number' && live >= 0;
    const floor = 0.04 * weights.idle;
    const target = Math.min(Math.max(hasLive ? live : energy, floor), 1.15);
    const breathAmp = 0.028 * weights.thinking + 0.01 * weights.idle;

    if (reduced) {
      smoothed.current = target;
    } else {
      smoothed.current = approach(smoothed.current, target, response, dt);
      spin.current = (spin.current + dt * Math.max(0, speed) * (0.12 + 0.43 * weights.thinking)) % (Math.PI * 2);
      shimmer.current = (shimmer.current + dt * Math.max(0, speed) * (9 + 24 * weights.listening)) % 1;
    }

    u.uTime.value = t;
    u.uAudio.value = smoothed.current;
    u.uDistort.value = distort;
    u.uFreq.value = freq;
    u.uFreqBoost.value = weights.listening;
    u.uSpin.value = spin.current;
    u.uBreath.value = 1 + breathAmp * Math.sin(t * 1.3);
    u.uRim.value = weights.connecting;
    u.uShimmerPhase.value = shimmer.current;
    u.uColorFrom.value.copy(palette.current.from).lerp(palette.current.errorFrom, weights.error);
    u.uColorTo.value.copy(palette.current.to).lerp(palette.current.errorTo, weights.error);
    if (!readyRef.current) {
      readyRef.current = true;
      onReady?.();
    }
  });

  return (
    <mesh>
      <icosahedronGeometry args={[1.2, 16]} />
      <shaderMaterial
        ref={matRef}
        vertexShader={vertexShader}
        fragmentShader={fragmentShader}
        uniforms={uniforms}
      />
    </mesh>
  );
};

export interface NebulaSceneProps {
  state: OrbState;
  speed: number;
  colorFrom: string;
  colorTo: string;
  levelRef?: RefObject<number>;
  onReady?: () => void;
}

export const NebulaScene = ({
  state,
  speed,
  colorFrom,
  colorTo,
  levelRef,
  onReady,
}: NebulaSceneProps) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const reduced = useReducedMotion();
  const [active, setActive] = useState(true);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    return observeActivity(canvas, setActive);
  }, []);

  return (
    <Canvas
      ref={canvasRef}
      frameloop={reduced || !active ? 'demand' : 'always'}
      camera={{ position: [0, 0, 3.6], fov: 45 }}
      gl={{ antialias: true, alpha: true }}
      dpr={[1, 2]}
      resize={{ offsetSize: true }}
    >
      <Sphere
        state={state}
        speed={speed}
        colorFrom={colorFrom}
        colorTo={colorTo}
        reduced={reduced}
        levelRef={levelRef}
        onReady={onReady}
      />
    </Canvas>
  );
};

