'use client';

import { useCallback, useEffect, useRef, useState } from 'react';
import { StaticRadialGradient } from '@paper-design/shaders-react';
import {
  blendEnergy,
  blendStates,
  clamp01,
  ERROR_COLOR_FROM,
  ERROR_COLOR_TO,
  hexToRgb,
  orbVars,
  type OrbProps,
  type OrbState,
} from '../../lib/orb-state';
import { mixHex, mixRgb, rgbToHex, shadeHex, tintHex, type Rgb } from '../../lib/orb-color';
import { useOrbAnimator, type OrbFrame } from '../../lib/use-orb-animator';
import { useReducedMotion } from '../../lib/use-reduced-motion';
import { useWebGLSupport } from '../../lib/use-webgl-support';

type ShaderUniforms = Record<string, number | number[] | number[][]>;

interface PaperMount {
  setUniforms: (uniforms: ShaderUniforms) => void;
  setFrame: (frame: number) => void;
}

interface PaperHost {
  paperShaderMount?: PaperMount;
}

const withAlpha = (hex: string, alpha: number) =>
  `${hex}${Math.round(alpha * 255)
    .toString(16)
    .padStart(2, '0')}`;

const brandPalette = (from: string, to: string): string[] => [
  shadeHex(to, 0.28),
  shadeHex(to, 0.08),
  to,
  mixHex(to, from, 0.55),
  from,
  tintHex(from, 0.55),
  tintHex(from, 0.94),
];

const BLOOM_ALPHA = [0, 0.45, 0.92, 1, 1, 1, 1];
const TRANSPARENT = '#00000000';
const BLOOM_SCALE = 1.5;
const BLOOM_MASK =
  'radial-gradient(circle closest-side, #000 50%, rgba(0,0,0,0.72) 68%, rgba(0,0,0,0.26) 85%, transparent 100%)';

const ERROR_PALETTE = brandPalette(ERROR_COLOR_FROM, ERROR_COLOR_TO);

const GL_ATTRIBUTES: WebGLContextAttributes = {
  antialias: false,
  powerPreference: 'low-power',
};

const STATIC_PHASE = 0.9;
const STATIC_ANGLE = 215;
const MAX_PIXEL_RATIO = 2;
const TAU = Math.PI * 2;

type RadianceTune = {
  spin: number;
  flow: number;
  radius: number;
  focalDistance: number;
  falloff: number;
  distortion: number;
  ripple: number;
  grain: number;
  outer: number;
  inner: number;
  beat: number;
  beatRate: number;
  error: number;
};

const TUNE: Record<OrbState, RadianceTune> = {
  idle: { spin: 6, flow: 0.25, radius: 1, focalDistance: 0.2, falloff: 0.16, distortion: 0.04, ripple: 0.05, grain: 0.03, outer: 0.2, inner: 0.2, beat: 0, beatRate: 0.3, error: 0 },
  connecting: { spin: 16, flow: 0.3, radius: 0.98, focalDistance: 0.16, falloff: -0.04, distortion: 0.05, ripple: 0.08, grain: 0.05, outer: 0.1, inner: 0.1, beat: 0.7, beatRate: 0.28, error: 0 },
  listening: { spin: 10, flow: 0.45, radius: 1, focalDistance: 0.24, falloff: 0.1, distortion: 0.06, ripple: 0.08, grain: 0.08, outer: 1, inner: 0.2, beat: 0, beatRate: 0.3, error: 0 },
  thinking: { spin: 48, flow: 0.5, radius: 1, focalDistance: 0.46, falloff: 0.22, distortion: 0.14, ripple: 0.14, grain: 0.06, outer: 0.1, inner: 0.1, beat: 1, beatRate: 0.5, error: 0 },
  speaking: { spin: 18, flow: 0.9, radius: 1.02, focalDistance: 0.28, falloff: 0.16, distortion: 0.1, ripple: 0.2, grain: 0.1, outer: 0.3, inner: 1, beat: 0, beatRate: 0.3, error: 0 },
  error: { spin: 80, flow: 1.2, radius: 1.06, focalDistance: 0.5, falloff: 0.5, distortion: 0.34, ripple: 0.25, grain: 0.14, outer: 0.2, inner: 0.2, beat: 0, beatRate: 0.3, error: 1 },
  disabled: { spin: 0, flow: 0, radius: 0.96, focalDistance: 0.1, falloff: -0.3, distortion: 0, ripple: 0, grain: 0.02, outer: 0, inner: 0, beat: 0, beatRate: 0.3, error: 0 },
};

const toShaderColor = ([r, g, b]: Rgb, alpha: number): number[] => [r / 255, g / 255, b / 255, alpha];

const livePalette = (colorFrom: string, colorTo: string, errorMix: number): Rgb[] =>
  brandPalette(colorFrom, colorTo).map((stop, index) =>
    mixRgb(hexToRgb(stop), hexToRgb(ERROR_PALETTE[index]), errorMix),
  );

export const RadianceOrb = ({
  state = 'idle',
  size = 168,
  speed = 1,
  colorFrom = '#fb7185',
  colorTo = '#7c3aed',
  levelRef,
  label = 'Assistant orb',
  className,
  ref,
}: OrbProps) => {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const sphereRef = useRef<HTMLDivElement>(null);
  const shaderRef = useRef<PaperHost | null>(null);
  const clockRef = useRef({ phase: 0, angle: STATIC_ANGLE, flow: 0, beat: 0, colors: '' });
  const reduced = useReducedMotion();
  const webgl = useWebGLSupport();
  const showShader = webgl === true;
  const [seed] = useState(() => {
    const tune = TUNE[state];
    return {
      ...tune,
      colors: livePalette(colorFrom, colorTo, tune.error).map((stop, index) =>
        withAlpha(rgbToHex(stop), BLOOM_ALPHA[index]),
      ),
    };
  });

  const setRootRef = (node: HTMLDivElement | null) => {
    rootRef.current = node;
    if (typeof ref === 'function') {
      ref(node);
    } else if (ref) {
      ref.current = node;
    }
  };

  const bindShader = useCallback((node: PaperHost | null) => {
    shaderRef.current = node;
  }, []);

  const onFrame = (frame: OrbFrame) => {
    const root = rootRef.current;
    if (!root) return;
    const clock = clockRef.current;
    const step = Math.max(0, frame.phase - clock.phase);
    clock.phase = frame.phase;
    const tune = blendStates(frame.weights, TUNE);
    const level = frame.reduced ? blendEnergy(frame.weights, STATIC_PHASE) : frame.level;
    clock.beat += step * tune.beatRate;
    const wave = frame.reduced ? 0.5 : 0.5 - 0.5 * Math.cos(clock.beat * TAU);
    const inner = level * tune.inner + wave * tune.beat * 0.4;
    const outer = level * tune.outer + wave * tune.beat * 0.3;
    clock.angle = (clock.angle + step * (tune.spin + inner * 24)) % 360;
    clock.flow += step * (tune.flow + inner * 0.8);
    const errorMix = clamp01(tune.error);
    const palette = livePalette(colorFrom, colorTo, errorMix);
    const from = rgbToHex(mixRgb(hexToRgb(colorFrom), hexToRgb(ERROR_COLOR_FROM), errorMix));
    const to = rgbToHex(mixRgb(hexToRgb(colorTo), hexToRgb(ERROR_COLOR_TO), errorMix));
    const colorKey = `${from}${to}`;
    if (colorKey !== clock.colors) {
      clock.colors = colorKey;
      root.style.setProperty('--orb-live-from', from);
      root.style.setProperty('--orb-live-to', to);
    }
    root.style.setProperty('--orb-level', level.toFixed(4));
    root.style.setProperty('--orb-outer', clamp01(outer).toFixed(4));
    const mount = shaderRef.current?.paperShaderMount;
    if (!mount) return;
    mount.setUniforms({
      u_colors: palette.map((stop, index) => toShaderColor(stop, BLOOM_ALPHA[index])),
      u_radius: tune.radius + outer * 0.08,
      u_focalDistance: tune.focalDistance + inner * 0.3,
      u_focalAngle: clock.angle,
      u_falloff: tune.falloff + inner * 0.5 + wave * tune.beat * 0.12,
      u_distortion: clamp01(tune.distortion + inner * 0.18),
      u_distortionShift: 0.2 + tune.ripple * Math.sin(clock.flow * TAU),
      u_grainMixer: tune.grain,
    });
  };

  useOrbAnimator(rootRef, { state, levelRef, speed, onFrame });

  useEffect(() => {
    if (state !== 'error' || reduced) return;
    const el = sphereRef.current;
    if (!el) return;
    const shake = el.animate(
      [
        { transform: 'translateX(0)' },
        { transform: 'translateX(-1.5px)' },
        { transform: 'translateX(3px)' },
        { transform: 'translateX(-2px)' },
        { transform: 'translateX(1px)' },
        { transform: 'translateX(0)' },
      ],
      { duration: 340, easing: 'ease-out' },
    );
    return () => shake.cancel();
  }, [state, reduced]);

  const bloom = Math.round(size * BLOOM_SCALE);
  const pad = (bloom - size) / 2;
  const liveFrom = `var(--orb-live-from, ${colorFrom})`;
  const liveTo = `var(--orb-live-to, ${colorTo})`;
  const fallbackLayers = [
    { key: 'brand', from: colorFrom, to: colorTo, visible: state !== 'error' },
    { key: 'error', from: ERROR_COLOR_FROM, to: ERROR_COLOR_TO, visible: state === 'error' },
  ].map(({ key, from: f, to: t, visible }) => ({
    key,
    visible,
    base: `radial-gradient(circle at 50% 46%, ${tintHex(f, 0.94)}, ${tintHex(f, 0.55)} 12%, ${f} 26%, ${mixHex(t, f, 0.55)} 42%, ${t} 58%, ${withAlpha(t, 0.4)} 76%, ${withAlpha(shadeHex(t, 0.28), 0)} 100%)`,
    glow: `radial-gradient(circle at 50% 46%, ${tintHex(f, 0.9)}, ${withAlpha(tintHex(f, 0.4), 0.65)} 20%, transparent 52%)`,
  }));

  return (
    <div
      ref={setRootRef}
      role="img"
      aria-label={label}
      data-state={state}
      className={className}
      style={{
        ...orbVars({ size, speed, colorFrom, colorTo }),
        width: size,
        height: size,
        position: 'relative',
        opacity: state === 'disabled' ? 0.5 : 1,
        filter: state === 'disabled' ? 'grayscale(0.85)' : 'grayscale(0)',
        scale: 'calc(1 + var(--orb-outer, 0) * 0.06)',
        transition: 'opacity 0.6s ease-out, filter 0.6s ease-out',
      }}
    >
      <div
        aria-hidden
        style={{
          position: 'absolute',
          inset: -pad,
          backgroundImage: `radial-gradient(circle, color-mix(in oklab, ${liveFrom} 50%, transparent), color-mix(in oklab, ${liveTo} 26%, transparent) 42%, transparent 72%)`,
          filter: `blur(${Math.round(size * 0.08)}px)`,
          opacity: 'calc(0.25 + var(--orb-outer, 0) * 0.6 + var(--orb-level, 0) * 0.1)',
          scale: 'calc(1 + var(--orb-outer, 0) * 0.1)',
        }}
      />
      <div
        ref={sphereRef}
        style={{
          position: 'absolute',
          inset: -pad,
          maskImage: BLOOM_MASK,
          WebkitMaskImage: BLOOM_MASK,
        }}
      >
        {showShader ? (
          <StaticRadialGradient
            ref={bindShader}
            width={bloom}
            height={bloom}
            colorBack={TRANSPARENT}
            colors={seed.colors}
            radius={seed.radius}
            focalDistance={seed.focalDistance}
            focalAngle={STATIC_ANGLE}
            falloff={seed.falloff}
            mixing={0.95}
            distortion={seed.distortion}
            distortionShift={0.2}
            distortionFreq={9}
            grainMixer={seed.grain}
            grainOverlay={0.04}
            speed={0}
            frame={0}
            fit="cover"
            scale={1}
            minPixelRatio={1}
            maxPixelCount={bloom * bloom * MAX_PIXEL_RATIO * MAX_PIXEL_RATIO}
            webGlContextAttributes={GL_ATTRIBUTES}
          />
        ) : (
          <div aria-hidden style={{ position: 'absolute', inset: 0 }}>
            {fallbackLayers.map((layer) => (
              <div
                key={layer.key}
                style={{
                  position: 'absolute',
                  inset: 0,
                  backgroundImage: layer.base,
                  opacity: layer.visible ? 1 : 0,
                  transition: 'opacity 0.35s ease',
                }}
              >
                <div
                  style={{
                    position: 'absolute',
                    inset: 0,
                    backgroundImage: layer.glow,
                    opacity: 'calc(0.25 + var(--orb-level, 0) * 0.75)',
                  }}
                />
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

'use client';

import { useCallback, useEffect, useRef, useState } from 'react';
import type { CSSProperties } from 'react';
import {
  blendStates,
  clamp01,
  ERROR_COLOR_FROM,
  ERROR_COLOR_TO,
  hexToRgb,
  orbVars,
  type OrbProps,
  type OrbState,
} from '../../lib/orb-state';
import { mixRgb, type Rgb } from '../../lib/orb-color';
import { useOrbAnimator, type OrbFrame } from '../../lib/use-orb-animator';
import { useWebGLSupport } from '../../lib/use-webgl-support';

type Vec3 = [number, number, number];

interface SheetParams extends Record<string, number> {
  speed: number;
  warp: number;
  ridge: number;
  sharp: number;
  zoom: number;
  exposure: number;
  mute: number;
  glow: number;
  rim: number;
  hear: number;
  voice: number;
  fade: number;
}

const STATE_TABLE: Record<OrbState, SheetParams> = {
  idle: { speed: 0.3, warp: 0.52, ridge: 0.48, sharp: 0.9, zoom: 0.94, exposure: 0.68, mute: 0.4, glow: 0.12, rim: 0.55, hear: 0, voice: 0, fade: 1 },
  connecting: { speed: 0.5, warp: 0.78, ridge: 0.72, sharp: 0.95, zoom: 0.97, exposure: 0.84, mute: 0.16, glow: 0.22, rim: 0.7, hear: 0, voice: 0, fade: 1 },
  listening: { speed: 0.55, warp: 0.66, ridge: 0.7, sharp: 1, zoom: 1, exposure: 1.04, mute: 0, glow: 0.3, rim: 0.85, hear: 1, voice: 0, fade: 1 },
  thinking: { speed: 1, warp: 1, ridge: 1, sharp: 1, zoom: 1, exposure: 1, mute: 0, glow: 0.28, rim: 0.8, hear: 0, voice: 0, fade: 1 },
  speaking: { speed: 0.78, warp: 0.72, ridge: 0.9, sharp: 1, zoom: 1, exposure: 0.96, mute: 0, glow: 0.34, rim: 0.8, hear: 0, voice: 1, fade: 1 },
  error: { speed: 0.5, warp: 0.7, ridge: 0.8, sharp: 1, zoom: 0.98, exposure: 0.94, mute: 0, glow: 0.3, rim: 0.8, hear: 0, voice: 0, fade: 1 },
  disabled: { speed: 0, warp: 0.42, ridge: 0.36, sharp: 0.88, zoom: 0.93, exposure: 0.42, mute: 0.92, glow: 0, rim: 0.35, hear: 0, voice: 0, fade: 0.62 },
};

const toUnit = ([r, g, b]: Rgb): Vec3 => [r / 255, g / 255, b / 255];

const rotateHue = ([r, g, b]: Rgb, degrees: number): Rgb => {
  const a = (degrees * Math.PI) / 180;
  const c = Math.cos(a);
  const s = Math.sin(a);
  const k = 1 / 3;
  const q = Math.sqrt(k);
  const m0 = c + (1 - c) * k;
  const m1 = k * (1 - c) - q * s;
  const m2 = k * (1 - c) + q * s;
  const clampC = (v: number) => Math.min(255, Math.max(0, v));
  return [
    clampC(r * m0 + g * m1 + b * m2),
    clampC(r * m2 + g * m0 + b * m1),
    clampC(r * m1 + g * m2 + b * m0),
  ];
};

const muteRgb = (rgb: Rgb, amount: number): Rgb => {
  const lum = rgb[0] * 0.2126 + rgb[1] * 0.7152 + rgb[2] * 0.0722;
  return mixRgb(rgb, [lum, lum, lum], amount);
};

const WHITE: Rgb = [255, 255, 255];

interface Palette {
  a: Vec3;
  b: Vec3;
  c: Vec3;
  d: Vec3;
  hi: Vec3;
  cool: Vec3;
  warm: Vec3;
  glow: Vec3;
}

const buildPalette = (from: Rgb, to: Rgb, mute: number): Palette => {
  const a = muteRgb(from, mute);
  const b = muteRgb(to, mute);
  const c = muteRgb(rotateHue(mixRgb(from, to, 0.35), -38), mute);
  const d = muteRgb(rotateHue(mixRgb(from, to, 0.65), 42), mute);
  const mid = mixRgb(a, b, 0.5);
  return {
    a: toUnit(a),
    b: toUnit(b),
    c: toUnit(c),
    d: toUnit(d),
    hi: toUnit(mixRgb(mid, WHITE, 0.82)),
    cool: toUnit(mixRgb(a, WHITE, 0.15)),
    warm: toUnit(mixRgb(d, WHITE, 0.1)),
    glow: toUnit(mid),
  };
};

const VERT = `
attribute vec2 aPos;
void main() {
  gl_Position = vec4(aPos, 0.0, 1.0);
}
`;

const FRAG = `
precision highp float;

uniform float uSize;
uniform float uPhase;
uniform float uLevel;
uniform float uWarp;
uniform float uRidge;
uniform float uSharp;
uniform float uZoom;
uniform float uExposure;
uniform float uGlow;
uniform float uRim;
uniform float uHear;
uniform float uFade;
uniform vec3 uColA;
uniform vec3 uColB;
uniform vec3 uColC;
uniform vec3 uColD;
uniform vec3 uHi;
uniform vec3 uCool;
uniform vec3 uWarm;
uniform vec3 uGlowCol;

const float RAD = 0.86;
const float SOFT = 0.005;

float hash(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x),
             mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x), f.y);
}

float fbm(vec2 p) {
  float s = 0.0;
  float a = 0.5;
  for (int i = 0; i < 4; i++) {
    s += a * noise(p);
    p = mat2(0.8, 0.6, -0.6, 0.8) * p * 2.03;
    a *= 0.5;
  }
  return s / 0.9375;
}

vec2 band(vec2 q, float drift, float offset, float amp, float mainY, float env, float soft) {
  float y = amp * env * sin(q.x * 1.0 + drift + offset);
  float d = abs(q.y - y);
  float line = 0.018 / (sqrt(d * d + soft * soft) + 0.026);
  float bd = max(0.0, max(q.y - max(mainY, y), min(mainY, y) - q.y));
  float fillB = 0.014 / (bd * bd * 5.0 + 0.06);
  return vec2(line, fillB);
}

vec3 sheet(vec2 p, float t) {
  float scale = 0.74 + uZoom * 0.34;
  vec2 q = p / scale;
  vec2 w = vec2(fbm(q * 1.1 + vec2(0.0, t * 0.09)), fbm(q * 1.1 + vec2(7.7, -t * 0.07))) - 0.5;
  q += uWarp * 0.075 * w;
  float xn = q.x;
  float envB = cos(1.57079633 * min(abs(0.9 * xn), 1.0));
  float env = envB * envB;
  float low = 0.5 + 0.5 * cos(t * 0.37);
  float mid = 0.5 + 0.5 * sin(t * 0.51 + 1.2);
  float high = 0.5 + 0.5 * cos(t * 0.73 + 2.1);
  float drift = t * 2.4;
  float mainAmp = 0.1 + uRidge * 0.17 + low * 0.018;
  float bandAmp = mainAmp + mid * 0.025 + high * 0.018;
  float mainY = mainAmp * env * sin(q.x * 1.1 + drift);
  float sep = 1.85 + uWarp * 0.12 + mid * 0.28;
  float soft = 0.03 / max(uSharp, 0.2) + mid * 0.006;

  vec2 b0 = band(q, drift, -sep, bandAmp, mainY, env, soft);
  vec2 b1 = band(q, drift, -sep * 0.34, bandAmp, mainY, env, soft);
  vec2 b2 = band(q, drift, sep * 0.34, bandAmp, mainY, env, soft);
  vec2 b3 = band(q, drift, sep, bandAmp, mainY, env, soft);
  float w0 = b0.x + b0.y;
  float w1 = b1.x + b1.y;
  float w2 = b2.x + b2.y;
  float w3 = b3.x + b3.y;
  float total = w0 + w1 + w2 + w3;
  float d0 = w0 * w0;
  float d1 = w1 * w1;
  float d2 = w2 * w2;
  float d3 = w3 * w3;
  vec3 spectral = (uColA * d0 + uColC * d1 + uColB * d2 + uColD * d3) / max(d0 + d1 + d2 + d3, 0.0001);
  float energy = (1.0 - exp(-max(total - 0.12, 0.0) * 0.75)) * env;
  float md = abs(q.y - mainY);
  float core = exp(-md * md / (0.0028 / max(uSharp, 0.2))) * env;

  float haze = fbm(q * 1.6 + vec2(t * 0.05, -t * 0.03));
  vec3 atmos = mix(uColD, uColB, smoothstep(-0.7, 0.7, q.y)) * (0.012 + 0.022 * haze);
  atmos += mix(uColA, uColC, haze) * 0.035 * exp(-q.y * q.y * 7.0) * haze;

  vec3 col = atmos + spectral * energy * 1.14;
  col += uHi * core * (0.2 + 0.1 * low);
  col = col / (1.0 + col * 0.18);
  col = mix(col, uHi, 0.06 * smoothstep(0.15, 1.15, dot(p, vec2(-0.32, 0.78))));
  col *= 1.0 - 0.3 * smoothstep(-0.1, 1.2, dot(p, vec2(0.45, -0.62)));
  return col;
}

float profile(float t) {
  float d = clamp(t, 0.0, 1.0);
  return 1.0 - sqrt(max(1.0 - (1.0 - d) * (1.0 - d), 0.0));
}

float lobe(vec2 n, vec2 dir, float cut, float power) {
  return pow(clamp((dot(n, dir) - cut) / max(1.0 - cut, 0.001), 0.0, 1.0), power);
}

vec3 over(vec3 dst, vec3 src, float a) {
  float k = clamp(a, 0.0, 1.0);
  return src * k + dst * (1.0 - k);
}

void main() {
  vec2 uv = (gl_FragCoord.xy * 2.0 - uSize) / uSize;
  float r = length(uv);
  float ang = atan(uv.y, uv.x);
  float t = uPhase;

  float contour = uHear * uLevel * (0.011 * sin(ang * 3.0 + t * 1.9) + 0.006 * sin(ang * 5.0 - t * 1.3 + 1.7));
  float rad = RAD * (1.0 + contour);
  vec3 glowCol = uGlowCol * (0.6 + 0.4 * uHear * uLevel);
  float glowAmt = uGlow * (1.0 + 0.9 * uHear * uLevel);

  if (r > rad * (1.01 + SOFT)) {
    vec3 halo = glowCol * glowAmt * exp(-(r - rad) * 11.0) * (1.0 - smoothstep(rad, 0.995, r));
    halo = clamp(halo, 0.0, 1.0);
